import { describe, expect, test } from "bun:test";

import { normalizeGeneratedLoader } from "./generated-loader-normalization.mjs";

describe("generated loader normalization", () => {
  test("strips generator directives while preserving loader code", () => {
    const source = `/* eslint-disable */
// @ts-nocheck -- generated by @napi-rs/cli
// prettier-disable generated output
const binding = load()
`;

    expect(normalizeGeneratedLoader(source)).toBe(
      "const binding = load()\n",
    );
  });

  test("does not finish live cleanup after scheduling throws", async () => {
    const generated = `async function drain() {
  while (hasLiveWork()) {
      await new Promise((resolve) => {
        __scheduleMacrotask(resolve)
      })
  }
  finishCleanup()
}`;
    const normalized = normalizeGeneratedLoader(generated);
    let scheduledCallback;
    let live = true;
    let finished = false;
    // oxlint-disable-next-line typescript/no-implied-eval -- Executes the normalized loader fixture so the scheduling handshake is tested end to end.
    const drain = Function(
      "hasLiveWork",
      "__scheduleMacrotask",
      "finishCleanup",
      `${normalized}; return drain`,
    )(
      () => live,
      (callback) => {
        scheduledCallback = callback;
        throw new Error("scheduling failed");
      },
      () => {
        finished = true;
      },
    );

    // oxlint-disable-next-line typescript/await-thenable, typescript/no-confusing-void-expression -- Function-created fixture types are opaque to the type-aware linter.
    await expect(drain()).rejects.toThrow(
      "scheduling failed",
    );
    live = false;
    scheduledCallback?.();
    await Promise.resolve();
    expect(finished).toBe(false);
  });
});
